+namespace sv_c3cf2c35b7764b5e81efcb0c6b0f5664.Services;
+
+/// <summary>
+/// Scoped service that polls for low-stock inventory alerts and notifies
+/// all subscribed components when new data arrives.
+/// Each circuit (user session) gets its own independent instance.
+/// </summary>
+public class InventoryAlertService : IDisposable
+{
+    private readonly WarehouseStateService _warehouseState;
+    private CancellationTokenSource? _pollCts;
+    private int _subscriberCount;
+    private readonly Lock _lock = new();
+
+    public int CurrentAlertCount { get; private set; }
+
+    public event Func<Task>? OnAlertCountChanged;
+
+    public InventoryAlertService(WarehouseStateService warehouseState)
+    {
+        _warehouseState = warehouseState;
+        _warehouseState.OnChange += HandleWarehouseChanged;
+    }
+
+    /// <summary>
+    /// Simulates a database query returning items below minimum stock levels.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        var count = Random.Shared.Next(0, 16);
+        return Task.FromResult(count);
+    }
+
+    /// <summary>
+    /// Called by components to start/join polling. Polling begins on the first
+    /// subscriber and stops when the last subscriber leaves.
+    /// </summary>
+    public void Subscribe()
+    {
+        lock (_lock)
+        {
+            _subscriberCount++;
+            if (_subscriberCount == 1)
+            {
+                StartPolling();
+            }
+        }
+    }
+
+    public void Unsubscribe()
+    {
+        lock (_lock)
+        {
+            _subscriberCount--;
+            if (_subscriberCount <= 0)
+            {
+                _subscriberCount = 0;
+                StopPolling();
+            }
+        }
+    }
+
+    private void StartPolling()
+    {
+        _pollCts = new CancellationTokenSource();
+        var token = _pollCts.Token;
+        _ = PollLoopAsync(token);
+    }
+
+    private void StopPolling()
+    {
+        _pollCts?.Cancel();
+        _pollCts?.Dispose();
+        _pollCts = null;
+    }
+
+    private async Task PollLoopAsync(CancellationToken cancellationToken)
+    {
+        while (!cancellationToken.IsCancellationRequested)
+        {
+            try
+            {
+                var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
+                CurrentAlertCount = count;
+                await NotifySubscribers();
+                await Task.Delay(TimeSpan.FromSeconds(10), cancellationToken);
+            }
+            catch (TaskCanceledException)
+            {
+                break;
+            }
+        }
+    }
+
+    private void HandleWarehouseChanged()
+    {
+        // Restart polling immediately with the new warehouse
+        lock (_lock)
+        {
+            if (_subscriberCount > 0)
+            {
+                StopPolling();
+                StartPolling();
+            }
+        }
+    }
+
+    private async Task NotifySubscribers()
+    {
+        if (OnAlertCountChanged is not null)
+        {
+            await OnAlertCountChanged.Invoke();
+        }
+    }
+
+    public void Dispose()
+    {
+        _warehouseState.OnChange -= HandleWarehouseChanged;
+        StopPolling();
+        OnAlertCountChanged = null;
+    }
+}
