@page "/dashboard"
@using sv_c3cf2c35b7764b5e81efcb0c6b0f5664.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Warehouse Dashboard</PageTitle>

<h2>Warehouse Dashboard</h2>

<div class="card mb-4">
    <div class="card-header">
        <strong>Current Site:</strong> @WarehouseState.CurrentWarehouseName
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum stock level:
            <span class="badge @(AlertService.CurrentAlertCount > 0 ? "bg-danger" : "bg-success") fs-5">
                @AlertService.CurrentAlertCount
            </span>
        </p>
        <p class="text-muted">
            <small>Polling every 10 seconds for warehouse <code>@WarehouseState.CurrentWarehouseId</code>. Last update: @_lastUpdate.ToString("HH:mm:ss")</small>
        </p>
    </div>
</div>

<div class="card">
    <div class="card-header">Inventory Summary</div>
    <div class="card-body">
        <p>This panel would show detailed inventory data for <strong>@WarehouseState.CurrentWarehouseName</strong>.</p>
        <p>All components on this page react to warehouse changes via the shared <code>WarehouseStateService</code>.</p>
    </div>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertUpdated;
        AlertService.Subscribe();
    }

    private void OnWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertUpdated()
    {
        _lastUpdate = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertUpdated;
        AlertService.Unsubscribe();
    }
}

